using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using ConRoi.Investigation.V36.R107;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = UnityEngine.Object.FindFirstObjectByType<InvestigationSession>();
            if (!s)
                throw new Exception("Session missing");
            var outDir = "Test/Output/CleanCheckout/LiveSnapshot_" + DateTime.UtcNow.ToString("yyyyMMdd_HHmmss");
            Directory.CreateDirectory(outDir);
            File.WriteAllText(outDir + "/live-data.json", JsonUtility.ToJson(s.data, true));
            File.WriteAllText(outDir + "/context.txt", "Read-only snapshot, not game save/load and not UI proof.\nprofile=" + s.SavePath + "\npage=" + s.Page + "\nposition=" + s.movement.transform.position + "\nyaw=" + s.movement.transform.eulerAngles.y + "\npitch=" + s.eye.transform.localEulerAngles.x + "\nsceneDirty=" + UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene().isDirty);
            ScreenCapture.CaptureScreenshot(outDir + "/screen.png");
            r.Log("Preserved live data without Save(), Load(), stopping Play or saving scene: " + outDir);
        }
    }
}

